create or replace function public.current_user_business_role(p_business_id uuid) returns text language sql security definer set search_path=public,pg_temp stable as $$ select coalesce((select lower(role::text) from business_members where business_id=p_business_id and user_id=auth.uid() limit 1),''); $$;
create or replace function public.require_business_admin(p_business_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$ begin if not exists(select 1 from business_members where business_id=p_business_id and user_id=auth.uid() and lower(role::text) in ('owner','admin')) and not exists(select 1 from profiles where id=auth.uid() and coalesce(is_admin,false)) then raise exception 'business_admin_required'; end if; end; $$;
create or replace function public.create_business_promotion(p_business_id uuid,p_title text,p_description text default null,p_discount numeric default null,p_starts_at timestamptz default now(),p_ends_at timestamptz default null,p_location_id uuid default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin perform require_business_admin(p_business_id); insert into promotions(business_id,title,description,discount,active,starts_at,ends_at,location_id) values(p_business_id,p_title,p_description,p_discount,true,p_starts_at,p_ends_at,p_location_id) returning id into v_id; return v_id; end; $$;
create or replace function public.set_business_promotion_status(p_business_id uuid,p_promotion_id uuid,p_active boolean) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin perform require_business_admin(p_business_id); update promotions set active=p_active where id=p_promotion_id and business_id=p_business_id; return found; end; $$;
create or replace function public.create_business_event(p_business_id uuid,p_title text,p_description text default null,p_event_date date default null,p_event_time time default null,p_location_id uuid default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin perform require_business_admin(p_business_id); insert into business_events(business_id,title,description,event_date,event_time,location_id) values(p_business_id,p_title,p_description,p_event_date,p_event_time,p_location_id) returning id into v_id; return v_id; end; $$;
create or replace function public.create_business_qr(p_business_id uuid,p_location_id uuid,p_label text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin perform require_business_admin(p_business_id); if not exists(select 1 from locations where id=p_location_id and business_id=p_business_id) then raise exception 'location_not_owned_by_business'; end if; insert into qr_codes(location_id,label,active) values(p_location_id,p_label,true) returning id into v_id; return v_id; end; $$;
create or replace function public.set_business_qr_status(p_business_id uuid,p_qr_id uuid,p_active boolean) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin perform require_business_admin(p_business_id); update qr_codes q set active=p_active from locations l where q.id=p_qr_id and q.location_id=l.id and l.business_id=p_business_id; return found; end; $$;
create or replace function public.set_business_qr_customization(p_business_id uuid,p_qr_id uuid,p_customization jsonb) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin perform require_business_admin(p_business_id); update qr_codes q set customization=p_customization from locations l where q.id=p_qr_id and q.location_id=l.id and l.business_id=p_business_id; return found; end; $$;
create or replace function public.create_business_location(p_business_id uuid,p_name text,p_address text default null,p_city text default null,p_state text default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin perform require_business_admin(p_business_id); insert into locations(business_id,name,address,city,state,is_active) values(p_business_id,p_name,p_address,p_city,p_state,true) returning id into v_id; return v_id; end; $$;
create or replace function public.set_business_location_status(p_business_id uuid,p_location_id uuid,p_active boolean) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin perform require_business_admin(p_business_id); update locations set is_active=p_active where id=p_location_id and business_id=p_business_id; return found; end; $$;
create or replace function public.create_business_partner_program(p_business_id uuid,p_name text,p_preferred_access boolean default false,p_match_discount_bonus numeric default null,p_custom_perk text default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin perform require_business_admin(p_business_id); insert into partner_programs(business_id,name,enabled,preferred_access,match_discount_bonus,custom_perk) values(p_business_id,p_name,true,p_preferred_access,p_match_discount_bonus,p_custom_perk) returning id into v_id; return v_id; end; $$;
create or replace function public.set_business_partner_program_status(p_business_id uuid,p_program_id uuid,p_enabled boolean) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ begin perform require_business_admin(p_business_id); update partner_programs set enabled=p_enabled where id=p_program_id and business_id=p_business_id; return found; end; $$;
revoke all on function public.require_business_admin(uuid) from public; grant execute on function public.require_business_admin(uuid) to authenticated;
revoke all on function public.create_business_promotion(uuid,text,text,numeric,timestamptz,timestamptz,uuid) from public; grant execute on function public.create_business_promotion(uuid,text,text,numeric,timestamptz,timestamptz,uuid) to authenticated;
